// @ts-check

import { isThenable } from '../../../utils/IsThenable.js'

/** @typedef {import('../../InvocationContext.js').InvocationContext} InvocationContext */

/**
 * @param {InvocationContext} invocationContext
 * @returns {any[]}
 */
export function getCurrentCommandPayload(invocationContext) {
    const command = invocationContext.getCurrentCommand()
    if (command == null) {
        throw new Error('Expected current command')
    }
    return command.payload
}

export const handleResultWithAction = (
    /** @type {any} */ result,
    /** @type {function(any): any} */ action
) => {
    if (isThenable(result)) {
        return result.then((/** @type {any} */ result) => action(result.getValue()))
    }
    return action(result.getValue())
}
